from mypy.types import Union# Запускаем функцию с аргументомdef get_mask_card_number(card_number: Union[str]) -> str:    """Функция которая принимает на вход номер карты и возвращает ее маску"""    card_number = card_number.replace(" ", "")    masked_card_number = " ".join(        card_number[i : i + 4] for i in range(0, len(card_number), 4)    )    masked_card_number_list = list(masked_card_number)    for i in range(len(masked_card_number_list)):        if 7 <= i <= 13 and masked_card_number_list[i] != " ":            masked_card_number_list[i] = "*"    masked_card_number = "".join(masked_card_number_list)    return masked_card_numberprint(get_mask_card_number("1234567812345678"))def get_mask_account(account_number: Union[str]) -> str:    """    Маскирует номер счета, показывая только последние 4 цифры.    Перед ними добавляются две звездочки.    :param account_number: str, номер счета    :return: str, маскированный номер    """    # Проверка длины номера    if len(account_number) < 4:        raise ValueError("Номер счета должен содержать как минимум 4 цифры")    # Получаем последние 4 цифры    last_four = account_number[-4:]    # Формируем маску    masked_account = "**" + last_four    return masked_accountprint(get_mask_account("73654108430135874305"))